{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via unescaped user input",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The method concatenates the caller-provided searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially access or modify data beyond their permissions.",
      "remediation": "Rewrite the query to use a bind variable or escape the input. For example: `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` or use `String.escapeSingleQuotes(searchKey)` before concatenation. This prevents injection while still allowing dynamic search."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4,6",
      "explanation": "The class queries and updates fields (Email, Name, Birthdate, Phone) that are not granted read or edit permissions in the Contact Phone Editor permission set, exposing sensitive data and allowing unauthorized modifications.",
      "remediation": "Restrict the SOQL query to only the Phone field or use Security.stripInaccessible to remove non‑permitted fields before the query. For updates, use Security.stripInaccessible or explicitly set only the Phone field, and enforce WITH SECURITY_ENFORCED or user mode to respect FLS."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced in Aura-enabled class",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "1",
      "explanation": "The class is declared without sharing and is reachable via @AuraEnabled, so users can query Case records that they should not see according to sharing rules.",
      "remediation": "Declare the class with sharing or inherited sharing, or add WITH USER_MODE to the SOQL query to enforce sharing."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive System Permissions in Support Agent Tools",
      "severity": "Medium",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled, which give users unrestricted access to all data and the ability to run Apex. This far exceeds the described purpose of allowing tier‑1 support agents to view and close cases, enabling privilege escalation for internal users.",
      "remediation": "Remove the ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions from the permission set. Keep only the necessary object permissions for Case (allowRead, allowEdit) and any other minimal permissions required for the support workflow. Consider creating a separate, more restrictive permission set for Apex execution if needed."
    }
  ]
}
